#!/bin/sh
# d32-look-greeter ID | -check: give the login screen the greeter of Desktop Look ID (THEME B8, update answers 2 and 5).
# Root, through doas (DISTRO 3.5): the rule names this file only, e.g. "permit nopass :wheel cmd /usr/local/d32/sbin/d32-look-greeter".
# Only an id listed in looks.conf is accepted, and the file installed is the build's own greeter file of that look: the
# caller supplies nothing else. dtlogin reads Xresources.d at every greeter start, so the next login screen shows it.
# Generated by deep32-ws/theme/tools/gen.js (tools/gen/look.js).
set -eu
LOOKS=/usr/local/share/d32/theme/looks
DEST=/etc/dt/config/C/Xresources.d/9999.zz-d32
id=${1:-}
[ "$id" = -check ] && exit 0
case $id in ''|*[!a-z0-9]*) echo "d32-look-greeter: usage: d32-look-greeter ID" >&2; exit 2 ;; esac
grep -v '^#' "$LOOKS/looks.conf" | cut -d'|' -f1 | grep -qx "$id" || { echo "d32-look-greeter: no look named $id" >&2; exit 2; }
install -o root -g wheel -m 0444 "$LOOKS/$id/greeter" "$DEST"
echo "d32-look-greeter: the login screen now uses look $id"
